/* ============================================================
   LIQUID GLASS THEME
   ============================================================ */

/* --- Cosmic background --- */
#wpcontent {
  background:
    radial-gradient(ellipse 60% 50% at 15% 45%, rgba(59, 196, 149, 0.07) 0%, transparent 100%),
    radial-gradient(ellipse 55% 45% at 80% 20%, rgba(100, 130, 255, 0.10) 0%, transparent 100%),
    radial-gradient(ellipse 50% 60% at 65% 85%, rgba(180, 60, 255, 0.07) 0%, transparent 100%),
    linear-gradient(160deg, #030b1a 0%, #0a1635 30%, #12062a 60%, #040d1c 100%) !important;
  background-attachment: fixed !important;
}

/* Ambient floating orbs */
#wpcontent::before,
#wpcontent::after {
  content: '';
  position: fixed;
  border-radius: 50%;
  pointer-events: none;
  z-index: 0;
  animation: lg-float 10s ease-in-out infinite;
}
#wpcontent::before {
  width: 700px;
  height: 700px;
